 67	const makeReplayClaim = Effect.fn("SendblueReplayStore.makeReplayClaim")(
 68	  function* (
 69	    claimIdGenerator: SendblueReplayClaimIdGenerator["Service"],
 70	    key: SendblueReplayClaimKey
 71	  ) {
 72	    const claimedAtEpochMillis = yield* Clock.currentTimeMillis;
 73	    const claimId = yield* claimIdGenerator.next;
 74	    return { claimedAtEpochMillis, claimId, key, status: "claimed" as const };
 75	  }
 76	);
