 78	const encodeReplayRecord = (record: SendblueReplayRecordType) =>
 79	  Schema.encodeEffect(replayRecordJson)(record).pipe(
 80	    Effect.mapError(
 81	      () =>
 82	        new SendblueReplayStoreError({
 83	          message: "Unable to encode the Sendblue replay record.",
 84	        })
 85	    )
 86	  );
 87	
 88	const claimRecord = (claim: SendblueReplayClaim): SendblueReplayRecordType => ({
 89	  claimedAtEpochMillis: claim.claimedAtEpochMillis,
 90	  claimId: claim.claimId,
 91	  key: claim.key,
 92	  status: "claimed",
 93	});
 94	
 95	const terminalRecord = (
 96	  claim: SendblueReplayClaim,
 97	  status: "complete" | "uncertain",
 98	  completedAtEpochMillis: number,
 99	  completion?: SendblueReplayCompletion
100	): SendblueReplayRecordType => ({
101	  claimedAtEpochMillis: claim.claimedAtEpochMillis,
102	  claimId: claim.claimId,
103	  completedAtEpochMillis,
104	  key: claim.key,
105	  providerMessageHandle: completion?.providerMessageHandle,
106	  status,
107	});
