109	const deriveReplayKeys = (
110	  options: SendblueReplayStoreOptions,
111	  kind: "inbound" | "outbound",
112	  coordinates: readonly string[]
113	) =>
114	  keyedSendblueDigest(options.routingKey, [
115	    "replay",
116	    kind,
117	    ...coordinates,
118	  ]).pipe(
119	    Effect.flatMap((digest) => {
120	      const logicalKey = `${kind}:${digest}`;
121	      return Effect.all({
122	        key: Schema.decodeUnknownEffect(
123	          kind === "inbound"
124	            ? SendblueInboundClaimKey
125	            : SendblueOutboundClaimKey
126	        )(`${options.prefix}${logicalKey}`),
127	        logicalKey: Schema.decodeUnknownEffect(AtomicKeyValueStoreKey)(
128	          logicalKey
129	        ),
130	      });
131	    }),
132	    Effect.mapError(
133	      () =>
134	        new SendblueReplayStoreError({
135	          message: "Unable to derive the Sendblue replay key.",
136	        })
137	    )
138	  );
139	
140	const logicalReplayKey = (
141	  options: SendblueReplayStoreOptions,
142	  key: SendblueReplayClaimKey
143	) =>
144	  Match.value(key.startsWith(options.prefix)).pipe(
145	    Match.when(true, () =>
146	      Schema.decodeUnknownEffect(AtomicKeyValueStoreKey)(
147	        key.slice(options.prefix.length)
148	      )
149	    ),
150	    Match.when(false, () =>
151	      Effect.fail(
152	        new SendblueReplayStoreError({
153	          message: "The Sendblue replay claim key is invalid.",
154	        })
155	      )
156	    ),
157	    Match.exhaustive,
158	    Effect.mapError(
159	      () =>
160	        new SendblueReplayStoreError({
161	          message: "The Sendblue replay claim key is invalid.",
162	        })
163	    )
164	  );
