166	export const makeSendblueReplayStore = Effect.fn("SendblueReplayStore.make")(
167	  function* (options: SendblueReplayStoreOptions) {
168	    const atomic = yield* AtomicKeyValueStore;
169	    const claimIdGenerator = yield* SendblueReplayClaimIdGenerator;
170	    const claim = Effect.fn("SendblueReplayStore.claim")(function* (
171	      key: SendblueReplayClaimKey,
172	      logicalKey: typeof AtomicKeyValueStoreKey.Type
173	    ) {
174	      const replayClaim = yield* makeReplayClaim(claimIdGenerator, key);
175	      const encodedClaim = yield* encodeReplayRecord(claimRecord(replayClaim));
176	      const transaction = yield* Schema.decodeUnknownEffect(
177	        AtomicKeyValueStoreTransaction
178	      )({
179	        conditions: [{ _tag: "Absent", key: logicalKey }],
180	        mutations: [
181	          {
182	            _tag: "Set",
183	            key: logicalKey,
184	            ttl: options.leaseSeconds * 1000,
185	            value: encodedClaim,
186	          },
187	        ],
188	      }).pipe(
189	        Effect.mapError(
190	          () =>
191	            new SendblueReplayStoreError({
192	              message: "Unable to claim the Sendblue replay record.",
193	            })
194	        )
195	      );
196	      const outcome = yield* atomic.transact(transaction).pipe(
197	        Effect.mapError(
198	          () =>
199	            new SendblueReplayStoreError({
200	              message: "Unable to claim the Sendblue replay record.",
201	            })
202	        )
203	      );
204	      return yield* Match.value(outcome).pipe(
205	        Match.when("applied", () =>
206	          Effect.succeed({
207	            claim: replayClaim,
208	            status: "claimed" as const,
209	          })
210	        ),
211	        Match.when("conflict", () =>
212	          Effect.succeed({ status: "duplicate" as const })
213	        ),
214	        Match.exhaustive
215	      );
216	    });
217	    const retain = Effect.fn("SendblueReplayStore.retain")(function* (
218	      replayClaim: SendblueReplayClaim,
219	      logicalKey: typeof AtomicKeyValueStoreKey.Type,
220	      status: "complete" | "uncertain",
221	      expected: string,
222	      completion?: SendblueReplayCompletion
223	    ) {
224	      const completedAtEpochMillis = yield* Clock.currentTimeMillis;
225	      const value = yield* encodeReplayRecord(
226	        terminalRecord(replayClaim, status, completedAtEpochMillis, completion)
227	      );
228	      const transaction = yield* Schema.decodeUnknownEffect(
229	        AtomicKeyValueStoreTransaction
230	      )({
231	        conditions: [{ _tag: "Equals", key: logicalKey, value: expected }],
232	        mutations: [
233	          {
234	            _tag: "Set",
235	            key: logicalKey,
236	            ttl: options.ttlSeconds * 1000,
237	            value,
238	          },
239	        ],
240	      }).pipe(
241	        Effect.mapError(
242	          () =>
243	            new SendblueReplayStoreError({
244	              message: "Unable to transition the Sendblue replay record.",
245	            })
246	        )
247	      );
248	      return yield* atomic.transact(transaction);
249	    });
250	    const transition = Effect.fn("SendblueReplayStore.transition")(function* (
251	      replayClaim: SendblueReplayClaim,
252	      status: "complete" | "retryable" | "uncertain",
253	      completion?: SendblueReplayCompletion
254	    ) {
255	      const logicalKey = yield* logicalReplayKey(options, replayClaim.key);
256	      const expected = yield* encodeReplayRecord(claimRecord(replayClaim));
257	      const outcome = yield* Match.value(status).pipe(
258	        Match.when("retryable", () =>
259	          Schema.decodeUnknownEffect(AtomicKeyValueStoreTransaction)({
260	            conditions: [{ _tag: "Equals", key: logicalKey, value: expected }],
261	            mutations: [{ _tag: "Remove", key: logicalKey }],
262	          }).pipe(Effect.flatMap((transaction) => atomic.transact(transaction)))
263	        ),
264	        Match.when("complete", () =>
265	          retain(replayClaim, logicalKey, "complete", expected, completion)
266	        ),
267	        Match.when("uncertain", () =>
268	          retain(replayClaim, logicalKey, "uncertain", expected, completion)
269	        ),
270	        Match.exhaustive,
271	        Effect.mapError(
272	          () =>
273	            new SendblueReplayStoreError({
274	              message: "Unable to transition the Sendblue replay record.",
275	            })
276	        )
277	      );
278	      return yield* Match.value(outcome).pipe(
279	        Match.when("applied", () => Effect.void),
280	        Match.when("conflict", () =>
281	          Effect.fail(
282	            new SendblueReplayStoreError({
283	              message: "The Sendblue replay claim is no longer active.",
284	            })
285	          )
286	        ),
287	        Match.exhaustive
288	      );
289	    });
290	    return SendblueReplayStore.of({
291	      claimInbound: (messageHandle) =>
292	        deriveReplayKeys(options, "inbound", [messageHandle]).pipe(
293	          Effect.flatMap(({ key, logicalKey }) => claim(key, logicalKey))
294	        ),
295	      claimOutbound: (coordinates) =>
296	        deriveReplayKeys(options, "outbound", [
297	          coordinates.sessionId,
298	          coordinates.turnId,
299	          String(coordinates.stepIndex),
300	          String(coordinates.sequence),
301	        ]).pipe(
302	          Effect.flatMap(({ key, logicalKey }) => claim(key, logicalKey))
303	        ),
304	      complete: (replayClaim, completion) =>
305	        transition(replayClaim, "complete", completion),
306	      retryable: (replayClaim) => transition(replayClaim, "retryable"),
307	      uncertain: (replayClaim) => transition(replayClaim, "uncertain"),
308	    });
309	  }
310	);
